using UnityEngine;
using UnityEditor;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using ConRoi.Investigation.V36.R107;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = UnityEngine.Object.FindFirstObjectByType<InvestigationSession>();
            if (Application.dataPath != "C:/ConRoi_CheckoutTest/Assets" || s.Page != "inspect" || !s.SavePath.Contains("Nav_fixed_20261108"))
                throw new Exception("Fresh private launch required");
            var dir = "Test/Output/NavFix_fixed_20261108";
            Directory.CreateDirectory(dir);
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            w.minSize = w.maxSize = new Vector2(1920, 1101.2f);
            w.position = new Rect(0, 0, 1920, 1101.2f);
            w.Focus();
            var settings = InputSystem.settings;
            if (AssetDatabase.Contains(settings))
                throw new Exception("Runtime settings only");
            string prior = JsonUtility.ToJson(settings);
            settings.editorInputBehaviorInPlayMode = InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;
            settings.backgroundBehavior = InputSettings.BackgroundBehavior.IgnoreFocus;
            var kb = InputSystem.AddDevice<Keyboard>("NAV01_fixed");
            var mouse = InputSystem.AddDevice<Mouse>("NAV01_fixed");
            kb.MakeCurrent();
            mouse.MakeCurrent();
            InputActionMap map = null;
            UnityEngine.InputSystem.Utilities.ReadOnlyArray<InputDevice>? oldDevices = null;
            var b = new StringBuilder("fixed: fixed. Synthetic GameView UI + InputSystem. API fixture: Acquire(letter/slide/phone); 2 floor observations seeded later for navigation layout. No API page opening, mapping, Save or Load.\n");
            var q = new Queue<Action>();
            Action<bool, string> check = (v, m) =>
            {
                b.AppendLine((v ? "PASS " : "FAIL ") + m);
                if (!v)
                    throw new Exception(m);
            };
            Action<Key> key = k => InputSystem.QueueStateEvent(kb, new KeyboardState(k));
            Action release = () =>
            {
                InputSystem.QueueStateEvent(kb, new KeyboardState());
                InputSystem.QueueStateEvent(mouse, new MouseState());
            };
            Action<float, float> click = (x, y) =>
            {
                var p = new Vector2(x * Screen.width / 1200f, y * Screen.height / 800f + 55);
                w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
                w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
            };
            Action<char> type = c =>
            {
                w.SendEvent(new Event{type = EventType.KeyDown, character = c});
                w.SendEvent(new Event{type = EventType.KeyUp});
            };
            Action<string> shot = n => ScreenCapture.CaptureScreenshot(dir + "/" + n + ".png");
            Vector3 modalPosition = Vector3.zero;
            Quaternion modalEye = Quaternion.identity;
            int evidenceBefore = 0;
            Vector3 worldPosition = Vector3.zero;
            Quaternion worldEye = Quaternion.identity;
            q.Enqueue(() =>
            {
                check(s.Page == "inspect", "E controller route opened floor");
            });
            q.Enqueue(() => key(Key.F5));
            q.Enqueue(() =>
            {
                release();
                check(File.Exists(s.SavePath), "F5 in inspected object");
            });
            q.Enqueue(() => key(Key.R));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "", "R leaves inspected object");
            });
            q.Enqueue(() => key(Key.F6));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "inspect" && !s.Paused, "F6 restores inspection without stuck pause");
            });
            q.Enqueue(() => key(Key.P));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "dossier", "P works after inspection load");
            });
            q.Enqueue(() => click(130, 138));
            q.Enqueue(() =>
            {
                check(s.Page == "cipher", "Cipher for typing guard");
                click(285, 484);
            });
            q.Enqueue(() => key(Key.P));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "cipher", "P remains a text input key while a field is focused, does not open dossier");
            });
            q.Enqueue(() => click(130, 103));
            q.Enqueue(() => key(Key.P));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "dossier", "P works again immediately after closing focused field");
            });
            q.Enqueue(() => key(Key.P));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "", "P closes dossier after typing guard");
                map = InputSystem.ListEnabledActions().First(a => a.name == "Move" && a.actionMap.name == "Gameplay").actionMap;
                oldDevices = map.devices;
                map.devices = new InputDevice[]{kb, mouse};
            });
            foreach (var k in new[]{Key.W, Key.S, Key.A, Key.D})
            {
                Key direction = k;
                q.Enqueue(() =>
                {
                    worldPosition = s.movement.transform.position;
                    key(direction);
                });
                q.Enqueue(() =>
                {
                    release();
                    check(Vector2.Distance(new Vector2(worldPosition.x, worldPosition.z), new Vector2(s.movement.transform.position.x, s.movement.transform.position.z)) > .05f, "Controller direction " + direction + " moves after UI");
                });
            }

            q.Enqueue(() =>
            {
                check(s.movement.controller.isGrounded, "Controller remains grounded");
                shot("tail-world-1080");
            });
            double next = EditorApplication.timeSinceStartup + 2;
            EditorApplication.CallbackFunction f = null;
            Action finish = () =>
            {
                EditorApplication.update -= f;
                release();
                if (map != null)
                    map.devices = oldDevices;
                InputSystem.RemoveDevice(kb);
                InputSystem.RemoveDevice(mouse);
                JsonUtility.FromJsonOverwrite(prior, settings);
                File.WriteAllText(dir + "/tail.txt", b.ToString());
                File.WriteAllText(dir + "/tail-live.json", JsonUtility.ToJson(s.data, true));
            };
            int step = 0;
            f = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + .4;
                try
                {
                    if (q.Count == 0)
                    {
                        finish();
                        return;
                    }

                    q.Dequeue()();
                    File.WriteAllText(dir + "/tail-progress.txt", "step=" + (++step) + " remaining=" + q.Count + " page=" + s.Page + "\n" + b);
                }
                catch (Exception e)
                {
                    b.AppendLine("FAIL " + e);
                    finish();
                }
            };
            EditorApplication.update += f;
            r.Log("UI suite queued: fixed; inspect eventual suite.txt, not callback registration.");
        }
    }
}

